import pytest


def parity(x: int) -> bool:
    """True when the byte x (an int from 0 to 255) has an odd number of set bits."""
    return bin(x).count("1") % 2 == 1


def test_parity_zero() -> None:
    assert parity(0) is False


def test_parity_single_bits() -> None:
    for i in range(8):
        assert parity(1 << i) is True


def test_parity_all_ones() -> None:
    assert parity(255) is False


def test_parity_known_values() -> None:
    assert parity(3) is False
    assert parity(7) is True
    assert parity(0b10101010) is False
    assert parity(0b10000001) is False
    assert parity(0b11100000) is True


def test_parity_matches_popcount() -> None:
    for x in range(256):
        assert parity(x) is (bin(x).count("1") % 2 == 1)


def test_parity_flipping_one_bit_toggles() -> None:
    for x in range(256):
        for i in range(8):
            assert parity(x ^ (1 << i)) is (not parity(x))

